package docgen

import "github.com/vpn-kongtrol/kongtrol/internal/i18n"

// Doc-only texts of the generated references, ES + EN (parity tested in
// text_test.go). Command help itself comes from internal/i18n (help.*),
// so the docs say exactly what `kongtrol --help` says.

func text(lang i18n.Lang, key string) string {
	if s, ok := docText[lang][key]; ok {
		return s
	}
	return docText[i18n.ES][key]
}

func fieldDesc(lang i18n.Lang, path string) (string, bool) {
	s, ok := fieldText[lang][path]
	return s, ok && s != ""
}

